import{_ as r,a0 as l,w as p,s as a,I as o,x as t,a1 as s,A as i,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"怎樣在 Linux 終端下使用 dd 命令創建一個臨場 USB 驅動器 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在 Linux 終端下使用 dd 命令創建一個臨場 USB 驅動器 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在 Linux 終端下使用 dd 命令創建一個臨場 USB 驅動器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在 Linux 終端下使用 dd 命令創建一個臨場 USB 驅動器 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210908 How to Use the dd Command to Create a Live USB Drive in Linux Terminal -For Experts and Adventurers","title":"怎樣在 Linux 終端下使用 dd 命令創建一個臨場 USB 驅動器","tag":"202109","desc":""},"relativePath":"202109/20210908 How to Use the dd Command to Create a Live USB Drive in Linux Terminal -For Experts and Adventurers.md","filePath":"[post].md"}'),u={name:"202109/20210908 How to Use the dd Command to Create a Live USB Drive in Linux Terminal -For Experts and Adventurers.md"};function m(f,d,b,S,g,x){const e=l("Link");return p(),a("div",null,[d[32]||(d[32]=o("h1",{id:"怎樣在-linux-終端下使用-dd-命令創建一個臨場-usb-驅動器",tabindex:"-1"},[t("怎樣在 Linux 終端下使用 dd 命令創建一個臨場 USB 驅動器 "),o("a",{class:"header-anchor",href:"#怎樣在-linux-終端下使用-dd-命令創建一個臨場-usb-驅動器","aria-label":"Permalink to “怎樣在 Linux 終端下使用 dd 命令創建一個臨場 USB 驅動器”"},"​")],-1)),d[33]||(d[33]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/15/104940ucajv4o4zb8934ll.jpg",alt:""})],-1)),o("p",null,[d[1]||(d[1]=t("有很多的圖形化工具可以用來創建",-1)),d[2]||(d[2]=o("ruby",null,[t("臨場"),o("rt",null,"live")],-1)),d[3]||(d[3]=t(" USB 驅動器。Linux 上的 ",-1)),s(e,{href:"https://itsfoss.com/install-etcher-linux/"},{default:i(()=>[...d[0]||(d[0]=[t("Etcher",-1)])]),_:1}),d[4]||(d[4]=t(" 可能是最受歡迎的。為此，Ubuntu 也開發了自己的啓動盤創建工具。",-1))]),d[34]||(d[34]=o("p",null,[t("但是，資深 Linux 用户可能更喜歡使用 "),o("code",null,"dd"),t(" 命令在 Linux 終端中創建臨場 USB，這會更快速便捷。")],-1)),o("p",null,[d[6]||(d[6]=o("code",null,"dd",-1)),d[7]||(d[7]=t(" 命令是一個 ",-1)),s(e,{href:"https://itsfoss.com/gui-cli-tui/"},{default:i(()=>[...d[5]||(d[5]=[t("命令列",-1)])]),_:1}),d[8]||(d[8]=t(" 工具，它提供了用來複制和轉換文件的強大功能。",-1))]),d[35]||(d[35]=n('<p>一個常見的使用示例是，用户使用 <code>dd</code> 命令將 ISO 文件寫入到他們的外部存儲設備（例如 USB 驅動盤），以用來給他們的電腦或者筆記本安裝一個新的 Linux 發行版。</p><p>這就是我將在本教程中展示的內容。我將帶你認識需要的命令，從終端找到我們的 USB 驅動器，然後對 ISO 文件進行實際刷寫。</p><h3 id="使用-dd-命令從-iso-鏡像創建臨場-usb" tabindex="-1">使用 dd 命令從 ISO 鏡像創建臨場 USB <a class="header-anchor" href="#使用-dd-命令從-iso-鏡像創建臨場-usb" aria-label="Permalink to “使用 dd 命令從 ISO 鏡像創建臨場 USB”">​</a></h3><p>在我向你展示步驟前，讓我帶你快速過一下你將要使用到的命令並解釋它的作用。</p><p>這是一個使用命令刷寫 ISO 的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dd if=&quot;./filename.iso&quot; of=&quot;/dev/sdb&quot; status=&quot;progress&quot; conv=&quot;fsync&quot;</span></span></code></pre></div>',6)),o("p",null,[d[10]||(d[10]=t("讓我們來看看 ",-1)),s(e,{href:"https://linuxhandbook.com/dd-command/"},{default:i(()=>[...d[9]||(d[9]=[t("dd 命令",-1)])]),_:1}),d[11]||(d[11]=t(" 實際都做了些什麼。",-1))]),d[36]||(d[36]=n('<h4 id="理解-dd-命令" tabindex="-1">理解 dd 命令 <a class="header-anchor" href="#理解-dd-命令" aria-label="Permalink to “理解 dd 命令”">​</a></h4><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/09/dd-command-for-live-usb-creation.png?resize=800%2C450&amp;ssl=1" alt="Explanation of the dd command for live USB creation"></p><p>首先，你輸入 <code>dd</code>。沒錯，這就是你要運行的程序的名稱。</p><p>接下來，你指定 <code>if=&quot;./filename.iso&quot;</code>。<code>if</code> 代表<ruby>輸入文件<rt>input file</rt></ruby>，告訴 <code>dd</code> 命令你將要向外部存儲設備寫入哪個文件。</p><p>之後，你輸入 <code>of=&quot;/dev/sdb&quot;</code>。和 <code>if</code> 一樣，<code>of</code> 代表的是<ruby>輸出文件<rt>output file</rt></ruby>。</p><p>要記住的是，輸出文件在技術上不必是系統上的文件。你還可以指定諸如外部設備路徑之類的內容（如示例所示），它看起來像系統上的普通文件，但實際上指向連接到你機器的設備。</p><p><code>status</code> 可以設定為 3 個選項：<code>none</code>、<code>noxfer</code> 和 <code>progress</code>。</p><ul><li>你設置的 <code>progress</code> 選項將使 <code>dd</code> 任務顯示有關已將多少 ISO 文件傳輸到存儲驅動器的定期統計信息，以及對 <code>dd</code> 任務完成前需要多長時間的估計。</li><li>如果你改為設置 <code>none</code> 選項，<code>dd</code> 任務在寫入 ISO 文件期間只會打印錯誤消息，並且刪除進度條之類的內容。</li><li><code>noxfer</code> 選項隱藏了傳輸完成後打印的一些信息，例如從開始到完成所用的時間。</li></ul><p>最後，你將 <code>conv</code> 選項設置為 <code>fsync</code>。這會導致 <code>dd</code> 任務在整個 ISO 文件寫入 USB 驅動器之前不會報告成功寫入。</p><p>如果你省略這個選項，<code>dd</code> 任務會工作的很好（並且實際上可能看起來運行得更快），但你可能會發現你的系統需要很長時間才能告訴你移除 USB 驅動器是安全的，因為它會在後台完成 ISO 的內容寫入，從而允許你在此期間做其它事情。</p><p><strong>現在你明白了你必須做什麼，讓我們看看如何去做。</strong></p><blockquote><p><strong>注意事項</strong></p><p>命令列是把雙刃劍。當你在命令列使用類似於 <code>dd</code> 命令時必須十分小心。你必須確保你目標輸出文件是正確的設備。一個錯誤的步驟就可能會格式化你的系統硬盤，你的操作系統也會因此而損壞。</p></blockquote><h4 id="第-0-步-下載所需的-iso-鏡像" tabindex="-1">第 0 步: 下載所需的 ISO 鏡像 <a class="header-anchor" href="#第-0-步-下載所需的-iso-鏡像" aria-label="Permalink to “第 0 步: 下載所需的 ISO 鏡像”">​</a></h4><p>不用説，你需要有一個 ISO 鏡像文件才能將其刷寫到 USB 上。</p>',14)),o("p",null,[d[13]||(d[13]=t("我將使用 Ubuntu 20.04 ISO（可在此處",-1)),s(e,{href:"https://ubuntu.com/download/desktop/thank-you?version=20.04.2.0&architecture=amd64"},{default:i(()=>[...d[12]||(d[12]=[t("下載",-1)])]),_:1}),d[14]||(d[14]=t("）來測試我之前介紹的 ",-1)),d[15]||(d[15]=o("code",null,"dd",-1)),d[16]||(d[16]=t(" 命令。",-1))]),d[37]||(d[37]=n('<h4 id="第-1-步-獲取-usb-盤符" tabindex="-1">第 1 步: 獲取 USB 盤符 <a class="header-anchor" href="#第-1-步-獲取-usb-盤符" aria-label="Permalink to “第 1 步: 獲取 USB 盤符”">​</a></h4><p>插入你的 USB 驅動器。</p><p>我為 <code>of</code> 參數輸入的具體路徑是 <code>/dev/sdb</code>。USB 磁盤通常會標記為 <code>/dev/sdb</code>，但這不是硬性規定。</p><p>此路徑可能因你的系統而異，你可以使用 <code>lsblk</code> 命令確認 USB 磁盤的路徑。只需從列表中查找一個看起來像你的 USB 磁盤大小的驅動器，就可以了。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/dd_disks.png?resize=753%2C264&amp;ssl=1" alt=""></p><p>如果你更熟悉 GUI 程序，還可以使用 GNOME Disks 等工具找到驅動器的路徑。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/dd_gnome_disks.png?resize=800%2C440&amp;ssl=1" alt=""></p><p>現在你已經確認了外部驅動器的路徑，讓我們開始創建臨場 USB。</p><h4 id="第-2-步-將-iso-文件寫入-usb-磁盤" tabindex="-1">第 2 步：將 ISO 文件寫入 USB 磁盤 <a class="header-anchor" href="#第-2-步-將-iso-文件寫入-usb-磁盤" aria-label="Permalink to “第 2 步：將 ISO 文件寫入 USB 磁盤”">​</a></h4><p>在下載 ISO 文件的目錄打開一個終端，然後運行以下命令（如果 <code>/dev/sdb</code> 與你的存儲設備名稱不同，請記住將其替換）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dd if=&quot;./ubuntu-20.04.2.0-desktop-amd64.iso&quot; of=&quot;/dev/sdb&quot; status=&quot;progress&quot; conv=&quot;fsync&quot;</span></span></code></pre></div><p>之後，讓 <code>dd</code> 去做剩下的事情，它會在完成後打印一條完成消息：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/dd-iso-write.png?resize=800%2C322&amp;ssl=1" alt=""></p><p>就像這樣，你已經在 Linux 終端中使用 <code>dd</code> 命令刷寫了 ISO 文件！</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>現在，你可以通過終端做更多的事情，讓你的工作效率大大提高。</p><p>對 <code>dd</code> 命令有任何沒解決的問題，或者無法正常工作？請隨時在下面的評論部分中留下你的問題。</p><hr>',18)),o("p",null,[d[18]||(d[18]=t("via: ",-1)),s(e,{href:"https://itsfoss.com/live-usb-with-dd-command/"},{default:i(()=>[...d[17]||(d[17]=[t("https://itsfoss.com/live-usb-with-dd-command/",-1)])]),_:1})]),o("p",null,[d[23]||(d[23]=t("作者：",-1)),s(e,{href:"https://itsfoss.com/author/hunter/"},{default:i(()=>[...d[19]||(d[19]=[t("Hunter Wittenborn",-1)])]),_:1}),d[24]||(d[24]=t(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...d[20]||(d[20]=[t("lujun9972",-1)])]),_:1}),d[25]||(d[25]=t(" 譯者：",-1)),s(e,{href:"https://github.com/perfiffer"},{default:i(()=>[...d[21]||(d[21]=[t("perfiffer",-1)])]),_:1}),d[26]||(d[26]=t(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:i(()=>[...d[22]||(d[22]=[t("wxy",-1)])]),_:1})]),o("p",null,[d[29]||(d[29]=t("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...d[27]||(d[27]=[t("LCTT",-1)])]),_:1}),d[30]||(d[30]=t(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:i(()=>[...d[28]||(d[28]=[t("Linux中國",-1)])]),_:1}),d[31]||(d[31]=t(" 榮譽推出",-1))])])}const h=r(u,[["render",m]]);export{U as __pageData,h as default};
